// Butonla LED kontrolü: her basışta LED açılır / kapanır
const int BUTON = 2;   // butonun bir bacağı D2, diğeri GND
const int LED = 8;     // D8 -> LED -> 220 ohm direnç -> GND

bool ledAcik = false;
bool oncekiDurum = HIGH;   // INPUT_PULLUP: basılmamışken HIGH

void setup() {
  pinMode(BUTON, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
}

void loop() {
  bool durum = digitalRead(BUTON);

  // HIGH -> LOW geçişi = butona yeni basıldı
  if (oncekiDurum == HIGH && durum == LOW) {
    ledAcik = !ledAcik;
    digitalWrite(LED, ledAcik);
    delay(30);             // kontak titreşimini (bounce) atla
  }
  oncekiDurum = durum;
}
